style.css:
@-moz-document url-prefix("https://www.youtube.com/"), url-prefix("http://www.youtube.com/") {
/* ===== Infinity Variables ===== */
:root {
  --gojo-bg: #05070d;
  --gojo-card: #0e1629;
  --gojo-text: #e9f4ff;
  --gojo-muted: #9ab6d9;

  --gojo-cyan: #0ff;
  --gojo-blue: #3b82f6;
  --gojo-electric: #00eaff;
  --gojo-pink: #ff00ff;

  --gojo-radius: 18px;
  --gojo-glow: 0 0 18px rgba(0,229,255,0.7), 0 0 28px rgba(59,130,246,0.45);
}

/* ===== Background with animated aura ===== */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 30% 40%, rgba(0,229,255,0.15), transparent 70%),
              radial-gradient(circle at 70% 60%, rgba(255,0,255,0.12), transparent 70%),
              #05070d;
  background-size: 200% 200%;
  animation: auraShift 20s infinite alternate ease-in-out;
  z-index: -1;
}

@keyframes auraShift {
  from { background-position: 0% 50%; }
  to { background-position: 100% 50%; }
}

/* ===== Cards & Thumbnails ===== */
ytd-rich-item-renderer {
  background: rgba(14,22,41,0.8) !important;
  border-radius: var(--gojo-radius) !important;
  border: 1px solid rgba(0,229,255,0.25) !important;
  box-shadow: var(--gojo-glow) !important;
  overflow: hidden;
}
ytd-rich-item-renderer:hover {
  transform: translateY(-4px) scale(1.02);
  transition: all 0.3s ease;
  box-shadow: 0 0 24px rgba(0,229,255,0.9), 0 0 40px rgba(255,0,255,0.5);
}

ytd-thumbnail img {
  border-radius: 14px !important;
  transition: all 0.3s ease;
}
ytd-thumbnail:hover img {
  filter: brightness(1.15) saturate(1.3) drop-shadow(0 0 12px rgba(0,229,255,0.7));
  transform: scale(1.04);
}

/* ===== Video Title Glow ===== */
#video-title {
  color: var(--gojo-text) !important;
  text-shadow: 0 0 12px rgba(0,229,255,0.6), 0 0 24px rgba(255,0,255,0.4);
  font-weight: 800 !important;
}

/* ===== Header / Search ===== */
#masthead-container {
  background: rgba(5,7,13,0.8) !important;
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,229,255,0.3);
  box-shadow: 0 0 24px rgba(0,229,255,0.4);
}

/* animated search glow */
ytd-searchbox {
  border-radius: 999px !important;
  border: 2px solid transparent !important;
  background: linear-gradient(#0e1629, #0e1629) padding-box,
              linear-gradient(90deg, #0ff, #3b82f6, #ff00ff, #0ff) border-box;
  animation: neonBorder 8s linear infinite;
}
@keyframes neonBorder {
  0% { border-image: linear-gradient(90deg, #0ff, #3b82f6, #ff00ff, #0ff) 1; }
  100% { border-image: linear-gradient(450deg, #0ff, #3b82f6, #ff00ff, #0ff) 1; }
}

/* ===== Like / Subscribe Buttons ===== */
ytd-subscribe-button-renderer yt-button-shape button {
  background: linear-gradient(90deg, #3b82f6, #00eaff, #ff00ff) !important;
  border-radius: 999px !important;
  color: #fff !important;
  text-shadow: 0 0 8px #000;
  animation: pulseSub 3s infinite ease-in-out;
}
@keyframes pulseSub {
  0%, 100% { box-shadow: 0 0 12px rgba(0,229,255,0.6); }
  50% { box-shadow: 0 0 24px rgba(255,0,255,0.8); }
}

/* like button */
ytd-segmented-like-dislike-button-renderer button[aria-pressed="true"] {
  background: rgba(0,229,255,0.2) !important;
  border-radius: 12px !important;
  box-shadow: 0 0 16px rgba(0,229,255,0.8), inset 0 0 10px rgba(0,229,255,0.4);
}

/* ===== Video Player Glow ===== */
.ytp-chrome-bottom {
  background: rgba(5,7,13,0.85) !important;
  border-top: 1px solid rgba(0,229,255,0.3);
  box-shadow: 0 0 20px rgba(0,229,255,0.5);
}
.ytp-play-progress {
  background: linear-gradient(90deg, #0ff, #3b82f6, #ff00ff) !important;
  animation: progressShift 6s linear infinite;
}
@keyframes progressShift {
  0% { filter: hue-rotate(0deg); }
  100% { filter: hue-rotate(360deg); }
}
}
